// GlimpseListDelta is what changed in a collection of Glimpse, keyed by ID.
//
// Present names the groups carried: bit 0 Set, bit 1 Removed, bit 2 Patched.
// The ordinary tick carries Patched alone, so an unchanged group costs a bit
// rather than an empty array.
type GlimpseListDelta struct {
	Present uint64
	// Set carries an entity that arrived, or one replaced outright.
	Set []Glimpse
	// Removed carries the identity of an entity that left.
	Removed []uint32
	// Patched carries an entity that changed, as its identity and its delta.
	Patched []GlimpsePatch
	// index is scratch the diff reuses across ticks, so a steady state
	// allocates nothing after the first call. It is never encoded and never
	// ranged: every loop below walks a slice, which is what keeps the output
	// the same on two runs.
	index map[uint32]int32
}

// GlimpsePatch is one changed Glimpse: its identity, and what changed in it.
type GlimpsePatch struct {
	ID    uint32
	Delta GlimpseDelta
}

// diffGlimpseListInto fills d with what changed between two collections of Glimpse,
// and reports whether anything did.
//
// The order of the two slices is not compared: an entity is found by its
// identity, so a collection the game keeps in spawn order diffs the same as
// one it keeps sorted.
func diffGlimpseListInto(d *GlimpseListDelta, baseline, current []Glimpse) bool {
	d.Present = 0
	d.Set = d.Set[:0]
	d.Removed = d.Removed[:0]
	d.Patched = d.Patched[:0]
	if d.index == nil {
		d.index = make(map[uint32]int32, len(baseline))
	} else {
		clear(d.index)
	}
	for i := range baseline {
		d.index[baseline[i].ID] = int32(i)
	}
	for j := range current {
		i, ok := d.index[current[j].ID]
		if !ok {
			d.Set = append(d.Set, current[j])
			continue
		}
		// Marked seen, so the sweep below reports only what did not arrive.
		d.index[current[j].ID] = -1
		// The slot is grown into rather than appended to, so the delta nested
		// inside it -- and the scratch index inside that -- is the one the last
		// tick used. Appending a fresh value here would allocate a new index map
		// per changed entity per tick, which is the whole steady state.
		if len(d.Patched) < cap(d.Patched) {
			d.Patched = d.Patched[:len(d.Patched)+1]
		} else {
			d.Patched = append(d.Patched, GlimpsePatch{})
		}
		p := &d.Patched[len(d.Patched)-1]
		p.ID = current[j].ID
		if !diffGlimpseInto(&p.Delta, baseline[i], current[j]) {
			d.Patched = d.Patched[:len(d.Patched)-1]
		}
	}
	for i := range baseline {
		if d.index[baseline[i].ID] >= 0 {
			d.Removed = append(d.Removed, baseline[i].ID)
		}
	}
	if len(d.Set) > 0 {
		d.Present |= 1 << 0
	}
	if len(d.Removed) > 0 {
		d.Present |= 1 << 1
	}
	if len(d.Patched) > 0 {
		d.Present |= 1 << 2
	}
	return d.Present != 0
}

// cborIndexOfGlimpse finds an entity by identity, and reports -1 for one the
// collection does not hold.
func cborIndexOfGlimpse(s []Glimpse, id uint32) int {
	for i := range s {
		if s[i].ID == id {
			return i
		}
	}
	return -1
}

// cborSortGlimpse puts a collection in identity order.
//
// An insertion sort, because a collection is nearly sorted already after a
// tick that changed a few entities, and because it allocates nothing and
// pulls in no import on a wasm target.
func cborSortGlimpse(s []Glimpse) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j].ID < s[j-1].ID; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// applyGlimpseListDelta puts a collection delta back.
//
// Removals first, then patches, then arrivals: a patch names an entity the
// baseline held, and applying it after an arrival of the same identity would
// patch the wrong value. An identity a patch or a removal names and the
// collection does not hold means the baseline is not the one the sender
// diffed against, which is reported rather than ignored.
func applyGlimpseListDelta(v *[]Glimpse, d GlimpseListDelta) error {
	if d.Present&(1<<1) != 0 {
		for _, id := range d.Removed {
			k := cborIndexOfGlimpse(*v, id)
			if k < 0 {
				return &cbor.Error{Path: "Glimpse: the delta removes an entity this baseline does not hold", Err: cbor.ErrUnexpectedToken}
			}
			*v = append((*v)[:k], (*v)[k+1:]...)
		}
	}
	if d.Present&(1<<2) != 0 {
		for i := range d.Patched {
			k := cborIndexOfGlimpse(*v, d.Patched[i].ID)
			if k < 0 {
				return &cbor.Error{Path: "Glimpse: the delta patches an entity this baseline does not hold", Err: cbor.ErrUnexpectedToken}
			}
			if err := applyGlimpseDelta(&(*v)[k], d.Patched[i].Delta); err != nil {
				return err
			}
		}
	}
	if d.Present&(1<<0) != 0 {
		for i := range d.Set {
			k := cborIndexOfGlimpse(*v, d.Set[i].ID)
			if k < 0 {
				*v = append(*v, d.Set[i])
			} else {
				(*v)[k] = d.Set[i]
			}
		}
	}
	// Identity order, so a receiver fed deltas and a sender holding the same
	// entities encode to the same bytes, which is what a replay compares.
	cborSortGlimpse(*v)
	return nil
}

// appendGlimpseListDeltaCBOR appends a collection delta.
//
// Only the groups Present names are written, and Patched alternates identity
// and payload in one array rather than pairing them: a byte per element, and
// a nesting level per hierarchy level.
func appendGlimpseListDeltaCBOR(dst []byte, v GlimpseListDelta) []byte {
	n := 1
	for bit := 0; bit < 3; bit++ {
		if v.Present&(1<<uint(bit)) != 0 {
			n++
		}
	}
	dst = cbor.AppendArrayHeader(dst, n)
	dst = cbor.AppendUint(dst, v.Present)
	if v.Present&(1<<0) != 0 {
		dst = cbor.AppendArrayHeader(dst, len(v.Set))
		for i := range v.Set {
			dst = appendGlimpseCBORWorld(dst, v.Set[i])
		}
	}
	if v.Present&(1<<1) != 0 {
		dst = cbor.AppendArrayHeader(dst, len(v.Removed))
		for i := range v.Removed {
			dst = cbor.AppendUint(dst, uint64(v.Removed[i]))
		}
	}
	if v.Present&(1<<2) != 0 {
		dst = cbor.AppendArrayHeader(dst, len(v.Patched)*2)
		for i := range v.Patched {
			dst = cbor.AppendUint(dst, uint64(v.Patched[i].ID))
			dst = appendGlimpseDeltaCBOR(dst, v.Patched[i].Delta)
		}
	}
	return dst
}

// decodeGlimpseListDeltaCBOR reads a collection delta.
func decodeGlimpseListDeltaCBOR(r *cbor.Reader, v *GlimpseListDelta) error {
	n, indefinite, err := r.ReadArrayHeader()
	if err != nil {
		return err
	}
	if indefinite || n < 1 {
		return &cbor.Error{Offset: int64(r.Offset()), Path: "GlimpseListDelta", Err: cbor.ErrUnexpectedToken}
	}
	present, err := r.ReadUint64()
	if err != nil {
		return err
	}
	v.Present = present
	v.Set = v.Set[:0]
	v.Removed = v.Removed[:0]
	v.Patched = v.Patched[:0]
	read := 1
	if present&(1<<0) != 0 {
		count, indefinite, err := r.ReadArrayHeader()
		if err != nil {
			return err
		}
		if indefinite {
			return &cbor.Error{Offset: int64(r.Offset()), Path: "GlimpseListDelta", Err: cbor.ErrUnexpectedToken}
		}
		for k := 0; k < count; k++ {
			var x Glimpse
			if err := decodeGlimpseCBORWorld(r, &x); err != nil {
				return err
			}
			v.Set = append(v.Set, x)
		}
		read++
	}
	if present&(1<<1) != 0 {
		count, indefinite, err := r.ReadArrayHeader()
		if err != nil {
			return err
		}
		if indefinite {
			return &cbor.Error{Offset: int64(r.Offset()), Path: "GlimpseListDelta", Err: cbor.ErrUnexpectedToken}
		}
		for k := 0; k < count; k++ {
			rawid, err := r.ReadUint64()
			if err != nil {
				return err
			}
			id := uint32(rawid)
			v.Removed = append(v.Removed, id)
		}
		read++
	}
	if present&(1<<2) != 0 {
		count, indefinite, err := r.ReadArrayHeader()
		if err != nil {
			return err
		}
		if indefinite || count%2 != 0 {
			return &cbor.Error{Offset: int64(r.Offset()), Path: "GlimpseListDelta", Err: cbor.ErrUnexpectedToken}
		}
		for k := 0; k < count; k += 2 {
			rawid, err := r.ReadUint64()
			if err != nil {
				return err
			}
			id := uint32(rawid)
			var p GlimpsePatch
			p.ID = id
			if err := decodeGlimpseDeltaCBOR(r, &p.Delta); err != nil {
				return err
			}
			v.Patched = append(v.Patched, p)
		}
		read++
	}
	// A group this schema does not know: one item per remaining slot, which
	// is what keeps an older reader aligned when a group was appended.
	for ; read < n; read++ {
		if err := r.Skip(); err != nil {
			return err
		}
	}
	return nil
}

// UnitListDelta is what changed in a collection of Unit, keyed by ID.
//
// Present names the groups carried: bit 0 Set, bit 1 Removed, bit 2 Patched.
// The ordinary tick carries Patched alone, so an unchanged group costs a bit
// rather than an empty array.
type UnitListDelta struct {
	Present uint64
	// Set carries an entity that arrived, or one replaced outright.
	Set []Unit
	// Removed carries the identity of an entity that left.
	Removed []uint32
	// Patched carries an entity that changed, as its identity and its delta.
	Patched []UnitPatch
	// index is scratch the diff reuses across ticks, so a steady state
	// allocates nothing after the first call. It is never encoded and never
	// ranged: every loop below walks a slice, which is what keeps the output
	// the same on two runs.
	index map[uint32]int32
}

// UnitPatch is one changed Unit: its identity, and what changed in it.
type UnitPatch struct {
	ID    uint32
	Delta UnitDelta
}

// diffUnitListInto fills d with what changed between two collections of Unit,
// and reports whether anything did.
//
// The order of the two slices is not compared: an entity is found by its
// identity, so a collection the game keeps in spawn order diffs the same as
// one it keeps sorted.
func diffUnitListInto(d *UnitListDelta, baseline, current []Unit) bool {
	d.Present = 0
	d.Set = d.Set[:0]
	d.Removed = d.Removed[:0]
	d.Patched = d.Patched[:0]
	if d.index == nil {
		d.index = make(map[uint32]int32, len(baseline))
	} else {
		clear(d.index)
	}
	for i := range baseline {
		d.index[baseline[i].ID] = int32(i)
	}
	for j := range current {
		i, ok := d.index[current[j].ID]
		if !ok {
			d.Set = append(d.Set, current[j])
			continue
		}
		// Marked seen, so the sweep below reports only what did not arrive.
		d.index[current[j].ID] = -1
		// The slot is grown into rather than appended to, so the delta nested
		// inside it -- and the scratch index inside that -- is the one the last
		// tick used. Appending a fresh value here would allocate a new index map
		// per changed entity per tick, which is the whole steady state.
		if len(d.Patched) < cap(d.Patched) {
			d.Patched = d.Patched[:len(d.Patched)+1]
		} else {
			d.Patched = append(d.Patched, UnitPatch{})
		}
		p := &d.Patched[len(d.Patched)-1]
		p.ID = current[j].ID
		if !diffUnitInto(&p.Delta, baseline[i], current[j]) {
			d.Patched = d.Patched[:len(d.Patched)-1]
		}
	}
	for i := range baseline {
		if d.index[baseline[i].ID] >= 0 {
			d.Removed = append(d.Removed, baseline[i].ID)
		}
	}
	if len(d.Set) > 0 {
		d.Present |= 1 << 0
	}
	if len(d.Removed) > 0 {
		d.Present |= 1 << 1
	}
	if len(d.Patched) > 0 {
		d.Present |= 1 << 2
	}
	return d.Present != 0
}

// cborIndexOfUnit finds an entity by identity, and reports -1 for one the
// collection does not hold.
func cborIndexOfUnit(s []Unit, id uint32) int {
	for i := range s {
		if s[i].ID == id {
			return i
		}
	}
	return -1
}

// cborSortUnit puts a collection in identity order.
//
// An insertion sort, because a collection is nearly sorted already after a
// tick that changed a few entities, and because it allocates nothing and
// pulls in no import on a wasm target.
func cborSortUnit(s []Unit) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j].ID < s[j-1].ID; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// applyUnitListDelta puts a collection delta back.
//
// Removals first, then patches, then arrivals: a patch names an entity the
// baseline held, and applying it after an arrival of the same identity would
// patch the wrong value. An identity a patch or a removal names and the
// collection does not hold means the baseline is not the one the sender
// diffed against, which is reported rather than ignored.
func applyUnitListDelta(v *[]Unit, d UnitListDelta) error {
	if d.Present&(1<<1) != 0 {
		for _, id := range d.Removed {
			k := cborIndexOfUnit(*v, id)
			if k < 0 {
				return &cbor.Error{Path: "Unit: the delta removes an entity this baseline does not hold", Err: cbor.ErrUnexpectedToken}
			}
			*v = append((*v)[:k], (*v)[k+1:]...)
		}
	}
	if d.Present&(1<<2) != 0 {
		for i := range d.Patched {
			k := cborIndexOfUnit(*v, d.Patched[i].ID)
			if k < 0 {
				return &cbor.Error{Path: "Unit: the delta patches an entity this baseline does not hold", Err: cbor.ErrUnexpectedToken}
			}
			if err := applyUnitDelta(&(*v)[k], d.Patched[i].Delta); err != nil {
				return err
			}
		}
	}
	if d.Present&(1<<0) != 0 {
		for i := range d.Set {
			k := cborIndexOfUnit(*v, d.Set[i].ID)
			if k < 0 {
				*v = append(*v, d.Set[i])
			} else {
				(*v)[k] = d.Set[i]
			}
		}
	}
	// Identity order, so a receiver fed deltas and a sender holding the same
	// entities encode to the same bytes, which is what a replay compares.
	cborSortUnit(*v)
	return nil
}

